const items = $input.all();
const normalizedItems = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const headers = item.json.headers || {};

  let sourceType = 'unknown';
  let source = 'unknown';

  if (headers['x-github-event']) {
    sourceType = 'github';
    source = 'GitHub';
  } else if (body.sonarqube || body.project?.key) {
    sourceType = 'sonarqube';
    source = 'SonarQube';
  } else if (
    body.event === 'pipeline_failed' ||
    body.event === 'pipeline_blocked' ||
    body.event === 'pipeline_success' ||
    body.job !== undefined ||
    body.jenkins === true
  ) {
    sourceType = 'jenkins';
    source = 'Jenkins';
  }

  const normalized = {
    incidentId: body.incidentId || `incident-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    source: source,
    sourceType: sourceType,
    repository: body.repository?.full_name || body.repository?.name || body.project?.key || body.repo || body.job || null,
    branch: body.ref?.replace('refs/heads/', '') || body.branch || body.git?.branch || null,
    commitSha: body.after || body.head_commit?.id || body.commit || body.revision?.sha || null,
    pullRequestNumber: body.pull_request?.number || body.number || null,
    title: body.title ||
           (body.job ? `${body.job} - Build #${body.build_number || 'N/A'}` : null) ||
           body.head_commit?.message?.split('\n')[0] ||
           body.message ||
           'Untitled Incident',
    description: body.description || body.build_url || body.head_commit?.message || body.message || '',
    severity: body.severity || body.rule?.severity?.toLowerCase() || 'medium',
    environment: body.environment || body.deployment?.environment || 'production',
    logs: body.logs || body.console_output || (body.logs_url ? [body.logs_url] : []),
    changedFiles: body.commits?.[0]?.modified || body.head_commit?.modified || [],
    github: sourceType === 'github' ? body : null,
    sonarqube: sourceType === 'sonarqube' ? body : null,
    jenkins: sourceType === 'jenkins' ? {
      event: body.event,
      job: body.job,
      build_number: body.build_number,
      build_url: body.build_url,
      logs_url: body.logs_url,
      severity: body.severity,
      status: body.status || body.build?.status || 'FAILURE',
      sonar_project_key: body.sonar_project_key || body.sonarProjectKey || null,
      failed_stages: body.failed_stages || [],
      error_messages: body.error_messages || [],
      stage_details: body.stage_details || {},
      security_summary: body.security_summary || {},
      test_summary: body.test_summary || {}
    } : null,
    createdAt: new Date().toISOString()
  };

  normalizedItems.push({ json: normalized });
}

return normalizedItems;

